export function icon(name,className=''){return `<svg class="gesture-icon ${className}" viewBox="0 0 64 64" aria-hidden="true">${icons[name]||icons.palm}</svg>`;}
export function experienceMetric(metric,lang,topic){
  if(!metric)return null;
  const d=dictionary(lang),c=copy[lang],m={...metric,scope:metric.country||d.scopes[lang]};
  if(topic==='space'&&Number.isFinite(metric.raw.weightedPercentCovered)){
    m.rawValue=metric.raw.weightedPercentCovered;m.value=m.rawValue;m.short=number(m.value,lang,2)+'%';m.label='housingShare';m.unit=d.labels.housingShare;
    if(metric.partial&&metric.raw.countryDetails?.length===1)m.scope=countryName(metric.raw.countryDetails[0].iso2,lang);
  }
  m.title=c[topic+'Topic'];m.action=c[{shelter:'shadeAction',hold:'holdAction',space:'spaceAction'}[topic]];
  m.note=c[topic==='shelter'?'shadeNote':topic==='space'?'spaceNote':m.male!=null||m.label==='careRatio'?'holdNote':'careNoteSolo'];
  m.publication=m.label==='careRatio';
  return m;
}
export function facts(m,lang,topic){
  const d=dictionary(lang),c=copy[lang];if(!m)return [];
  if(topic==='shelter')return [{value:compact(m.value,lang),label:m.unit},{value:'≈ '+number(m.rate,lang,1),label:(m.label==='carbonGhg'?d.labels.ghg:d.labels.co2)+' '+c.perSecond}];
  if(topic==='hold'){
    const unit=m.label==='careRatio'?d.labels.careRatio:d.labels.careHours;
    const entries=[{value:m.short+(m.label==='careRatio'?'':' '+c.hour),label:d.women}];
    if(m.label==='careRatio'||m.male!=null)entries.push({value:m.label==='careRatio'?number(1,lang,0)+'×':number(m.male,lang,2)+' '+c.hour,label:d.men});
    return entries.map(e=>({...e,unit}));
  }
  const entries=[{value:m.short,label:m.label==='mortgage'?c.payment:m.unit}];
  if(m.label==='mortgage')entries.push({value:number(100,lang,0)+'%',label:c.income});
  else if(m.raw.reportedPeople)entries.push({value:compact(m.raw.reportedPeople,lang),label:d.labels.housingPeople});
  else if(m.raw.estimated&&m.raw.value)entries.push({value:'≈ '+compact(m.raw.value,lang),label:d.labels.housingPeople});
  return entries;
}
export function displayYear(m,lang){
  if(typeof m.year==='number')return new Intl.NumberFormat(locales[lang],{useGrouping:false}).format(m.year)+(m.publication?' · '+copy[lang].report:'');
  return String(m.year||'');
}
